cluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

